import{_ as e,o as r,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"From VMware & SAN to Proxmox & Ceph A Practical Migration Path","description":"","frontmatter":{"title":"From VMware & SAN to Proxmox & Ceph A Practical Migration Path","date":"2026-07-10T00:00:00.000Z","updated":"2026-07-10T00:00:00.000Z","tags":["Ceph","CephFS","分布式存储","存储集群","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/From_VMware_SAN_to_Proxmox_Ceph_A_Practical_Migration_Path.md","filePath":"posts/2026/From_VMware_SAN_to_Proxmox_Ceph_A_Practical_Migration_Path.md","lastUpdated":null}'),l={name:"posts/2026/From_VMware_SAN_to_Proxmox_Ceph_A_Practical_Migration_Path.md"};function i(n,a,s,h,p,u){return r(),o("div",null,[...a[0]||(a[0]=[t('<h2 id="演讲者简介" tabindex="-1">演讲者简介 <a class="header-anchor" href="#演讲者简介" aria-label="Permalink to &quot;演讲者简介&quot;">​</a></h2><p>本次演讲由 Wes Smith 主讲，他是 ICense 公司的系统管理员，专注于 Linux、Proxmox、开源工具以及数据中心基础设施领域。ICense 是一家 ASIC（Application-Specific Integrated Circuit）设计公司，主要客户涉及医疗、汽车和航空航天领域。由于芯片一旦流片（tapeout）后无法进行任何后硅修复，因此&quot;一次做对&quot;（first time right）是公司最核心的价值观，大量的自动化仿真验证贯穿整个芯片设计流程。</p><h2 id="起始环境与迁移动机" tabindex="-1">起始环境与迁移动机 <a class="header-anchor" href="#起始环境与迁移动机" aria-label="Permalink to &quot;起始环境与迁移动机&quot;">​</a></h2><h3 id="原有基础架构" tabindex="-1">原有基础架构 <a class="header-anchor" href="#原有基础架构" aria-label="Permalink to &quot;原有基础架构&quot;">​</a></h3><p>迁移前，ICense 的存储与虚拟化环境由以下组件构成：</p><ul><li><strong>虚拟化层</strong>：VMware vSphere，配备三台 ESXi 服务器</li><li><strong>块存储</strong>：SAN 设备，36 块 HDD，60TB 净容量，并配有 Veeam 备份服务器</li><li><strong>网络文件系统</strong>：TrueNAS NFS，主要用于存储仿真结果</li><li><strong>工程师工作站接入</strong>：约 10 台远程桌面，工程师通过 NFS 挂载访问仿真数据</li><li><strong>网络文件系统（遗留）</strong>：OpenAFS，作为全公司统一文件系统</li></ul><p>IO 工作负载非常轻量：平均仅 626 IOPS，峰值 10,000 IOPS，吞吐量平均约 11 MB/s，峰值 17 MB/s。</p><h3 id="迁移触发因素" tabindex="-1">迁移触发因素 <a class="header-anchor" href="#迁移触发因素" aria-label="Permalink to &quot;迁移触发因素&quot;">​</a></h3><ol><li><strong>Broadcom 收购 VMware</strong>：对未来许可策略和成本走向高度不确定，公司提前三年续签 vSphere 许可以争取时间评估替代方案。</li><li><strong>SAN 设备老化</strong>：容量已达 80%，且即将 EOL（End of Life），无法扩容也无法升级。替代方案要么功能不足、要么严重超规（有供应商报价提供 140 万 IOPS，完全过剩）。</li><li><strong>OpenAFS 的兼容性问题</strong>：客户端需要自定义 kernel module 或旧驱动，导致仿真主机出现 shell 卡死、内存泄漏，macOS 用户甚至需要强制重启。</li><li><strong>TrueNAS 单点故障</strong>：设备本身运行正常，但架构上存在单点故障风险，且同样面临 EOL。</li></ol><h2 id="proxmox-的选型逻辑" tabindex="-1">Proxmox 的选型逻辑 <a class="header-anchor" href="#proxmox-的选型逻辑" aria-label="Permalink to &quot;Proxmox 的选型逻辑&quot;">​</a></h2><p>Proxmox VE 之所以进入候选名单，主要原因包括：</p><ul><li>原生支持虚拟机、高可用（HA）、备份、快照等核心功能</li><li>完全开源，可在旧服务器上自由测试，无授权门槛</li><li>将 Ceph 作为企业级存储后端原生支持</li></ul><p>2023 年第四季度，演讲者在 HP C7000 刀片机箱上搭建了 PoC（概念验证）集群：两个 Proxmox 节点配备 ZFS 直连存储，加一台 quorum 设备。验证结果表明基本功能运转良好。</p><h2 id="选择-ceph-的核心理由" tabindex="-1">选择 Ceph 的核心理由 <a class="header-anchor" href="#选择-ceph-的核心理由" aria-label="Permalink to &quot;选择 Ceph 的核心理由&quot;">​</a></h2><p>相比 ZFS，Ceph 在以下方面更契合 ICense 的需求：</p><ul><li><strong>真正的共享存储</strong>：ZFS 只能提供基于异步复制的伪共享，Ceph 提供真正的多节点共享存储</li><li><strong>更优雅的故障处理</strong>：Ceph 的 OSD 失效恢复机制远优于 ZFS 复制场景</li><li><strong>横向扩展能力强</strong>：公司规模在增长，Ceph 可按需扩容，灵活适应不同负载</li><li><strong>无硬件兼容性列表限制</strong>：可运行在退役的仿真服务器上，充分利用旧硬件</li><li><strong>CephFS 有望替代 OpenAFS 和 NFS</strong>：这个收益在项目初期并未预料到，但在实施过程中逐步成为重要价值点</li></ul><h2 id="迁移过程与关键里程碑" tabindex="-1">迁移过程与关键里程碑 <a class="header-anchor" href="#迁移过程与关键里程碑" aria-label="Permalink to &quot;迁移过程与关键里程碑&quot;">​</a></h2><h3 id="_2025-年-1-月-深入学习-ceph" tabindex="-1">2025 年 1 月：深入学习 Ceph <a class="header-anchor" href="#_2025-年-1-月-深入学习-ceph" aria-label="Permalink to &quot;2025 年 1 月：深入学习 Ceph&quot;">​</a></h3><p>演讲者系统学习了 Ceph 文档，初期面对 OSD、MDS、MON、CephFS、RGW 等概念感到困惑，随后投入参加了一个为期三天的 Ceph 专项培训，收获颇丰。</p><p>两个关键认知：</p><ol><li><strong>避免超融合架构（Hyperconverged Infrastructure）</strong>：VM 与 Ceph 共享 CPU 资源会产生资源竞争，决定部署独立的外部 Ceph 集群</li><li><strong>深入理解集群内部机制</strong>：避免&quot;点点点&quot;式黑盒部署，需要在出现问题时能够独立排查</li></ol><h3 id="_2025-年-2-月-性能测试阶段" tabindex="-1">2025 年 2 月：性能测试阶段 <a class="header-anchor" href="#_2025-年-2-月-性能测试阶段" aria-label="Permalink to &quot;2025 年 2 月：性能测试阶段&quot;">​</a></h3><p>初期集群配置为 4 个 OSD 节点，仅使用 rados bench 进行基准测试，发现了一个明显异常：<strong>读取速度达 2.22 GB/s，但写入仅 130 MB/s</strong>。</p><p>通过性能监控面板发现大量写入等待状态（wait states），最终判断原因是所使用的 SSD <strong>没有掉电保护（power-loss protection）</strong>，导致写入性能极差。更换为支持掉电保护的 SAS/SATA SSD 后，写入性能显著提升。</p><h3 id="集群规模扩展" tabindex="-1">集群规模扩展 <a class="header-anchor" href="#集群规模扩展" aria-label="Permalink to &quot;集群规模扩展&quot;">​</a></h3><p>随着业务增长，集群逐步扩展至：</p><ul><li><strong>96 个 OSD</strong>，原始容量 368TB</li><li>新增多个 Proxmox 节点</li><li>双网络接口冗余（4 个交换机，共 8 个网络接口：4 个 Ceph public 网络，4 个 Ceph cluster 网络）</li><li>实施 CPU 调优，降低延迟</li></ul><h3 id="网络拓扑改造" tabindex="-1">网络拓扑改造 <a class="header-anchor" href="#网络拓扑改造" aria-label="Permalink to &quot;网络拓扑改造&quot;">​</a></h3><p>Proxmox Backup Server 备份任务曾导致严重性能抖动，甚至无法 SSH 登录 VM。根因是 Ceph public 网络走的是 1 Gbit 接口。演讲者通过重新规划网络拓扑（而非升级路由器）解决了这一问题，同时顺便重建了整个 PoC 集群（因为修改 MON 的 IP 地址流程复杂，重建反而更快）。</p><h3 id="cephfs-文件系统设计" tabindex="-1">CephFS 文件系统设计 <a class="header-anchor" href="#cephfs-文件系统设计" aria-label="Permalink to &quot;CephFS 文件系统设计&quot;">​</a></h3><p>最初考虑模仿 OpenAFS 部署一个大型单体文件系统，但深入了解 MDS 架构后，转变为<strong>多个独立的小型 CephFS 文件系统</strong>，主要出于故障隔离（blast radius 控制）考虑。</p><p>这一决策的代价是：更多文件系统 → 更多存储池 → 更多 PG → 更多 OSD → 需要更多 SSD。为此额外采购了 SSD，每个 OSD 节点配置 12 块，并新增了专用 MDS 服务器以提升元数据性能。</p><h3 id="smb-接入配置" tabindex="-1">SMB 接入配置 <a class="header-anchor" href="#smb-接入配置" aria-label="Permalink to &quot;SMB 接入配置&quot;">​</a></h3><p>由于大量 macOS 和 Windows 客户端需要访问 CephFS，采用 SMB 协议提供接入：</p><ul><li>针对 macOS 启用 <strong>VFS fruit 模块</strong>，性能提升显著</li><li>未使用 Tentacle 中的 SMB Manager 模块（该功能较新，观望社区反馈中；且尚不确定该模块是否支持 VFS fruit，若不支持则为阻塞性问题）</li></ul><h3 id="erasure-coding-池" tabindex="-1">Erasure Coding 池 <a class="header-anchor" href="#erasure-coding-池" aria-label="Permalink to &quot;Erasure Coding 池&quot;">​</a></h3><p>近期为归档数据引入了 <strong>Erasure Coding</strong> 存储池，用户首批测试反馈非常积极，性能体验明显优于旧系统。</p><h3 id="bluestore-elastic-shared-blobs-bug" tabindex="-1">BlueStore Elastic Shared Blobs Bug <a class="header-anchor" href="#bluestore-elastic-shared-blobs-bug" aria-label="Permalink to &quot;BlueStore Elastic Shared Blobs Bug&quot;">​</a></h3><p>在签订支持合同后的集群验收过程中，被告知存在 Squid 版本中 <strong>BlueStore Elastic Shared Blobs</strong> 的已知 bug（彼时尚未使用 Erasure Coding 池，但仍决定规避风险），通过重新部署所有 OSD 进行缓解，并将集群扩容推迟至圣诞维护窗口期。</p><p><strong>核心经验：在使用 Ceph 前，务必查阅当前版本的已知严重 bug 列表。</strong></p><h2 id="数据集特征与备份挑战" tabindex="-1">数据集特征与备份挑战 <a class="header-anchor" href="#数据集特征与备份挑战" aria-label="Permalink to &quot;数据集特征与备份挑战&quot;">​</a></h2><p>仿真数据集具有<strong>小文件密集型</strong>特征：</p><ul><li>总文件数约 7200 万个</li><li>总数据量约 27TB</li><li>平均文件大小约 373KB</li></ul><p>这对备份系统构成了较大压力，因为需要遍历整个目录树。相比之下，VMware 的 Changed Block Tracking（CBT）机制可以绕过这个问题。</p><p>为加速备份和元数据操作，新增了专用 NVMe 节点用于托管 CephFS 元数据池，并增设了第三个机箱用于部署新节点。</p><p>备份方案：使用 <strong>Proxmox Backup Server</strong>，实现 VM 磁盘与文件的磁盘到磁盘备份。</p><h2 id="故障案例复盘" tabindex="-1">故障案例复盘 <a class="header-anchor" href="#故障案例复盘" aria-label="Permalink to &quot;故障案例复盘&quot;">​</a></h2><h3 id="故障一-mds-主动节点维护引发仿真目录消失" tabindex="-1">故障一：MDS 主动节点维护引发仿真目录消失 <a class="header-anchor" href="#故障一-mds-主动节点维护引发仿真目录消失" aria-label="Permalink to &quot;故障一：MDS 主动节点维护引发仿真目录消失&quot;">​</a></h3><p>在对活跃 MDS 节点执行系统维护（<code>ceph orch host maintenance enter</code>）时，没有预先确认是否有足够内存在其他节点上重启 MDS，导致 MDS failover 失败，用户报告仿真目录不可见。</p><p><strong>教训</strong>：在对 MDS 节点执行维护前，必须确认备用节点有足够资源承接 MDS 角色切换。</p><h3 id="故障二-断电后-osd-状态异常" tabindex="-1">故障二：断电后 OSD 状态异常 <a class="header-anchor" href="#故障二-断电后-osd-状态异常" aria-label="Permalink to &quot;故障二：断电后 OSD 状态异常&quot;">​</a></h3><p>周六早晨断电恢复后，发现集群状态异常，但并未看到预期中的 PG 不可用或 OSD down/out 告警，令人困惑。进一步排查发现问题 OSD 分布在两台主机上，理论上应有部分 PG 阻塞 IO，但告警并未如此显示。</p><p>尝试启动 VM 时，多台 VM 在 GRUB 后卡住，初步判定 Ceph 集群存在异常。最终通过<strong>重启相关两台主机的 OSD 进程</strong>立即恢复正常。</p><p>推测原因：断电后，这两台主机上的 Ceph cluster 网络接口可能先于 public 网络接口启动，OSD 容器启动时只能感知到 cluster 网络，导致从外部看 OSD 既不显示为 down 也不可达。</p><h2 id="总体评估" tabindex="-1">总体评估 <a class="header-anchor" href="#总体评估" aria-label="Permalink to &quot;总体评估&quot;">​</a></h2><h3 id="需要慎重考虑的方面" tabindex="-1">需要慎重考虑的方面 <a class="header-anchor" href="#需要慎重考虑的方面" aria-label="Permalink to &quot;需要慎重考虑的方面&quot;">​</a></h3><ul><li><strong>Ceph 不是&quot;设置后忘记&quot;的系统</strong>，学习曲线真实存在</li><li><strong>更多自主责任</strong>：不像 SAN 那样可以直接呼叫 MSP 解决问题，需要更强的内部技术能力</li></ul><h3 id="收益与亮点" tabindex="-1">收益与亮点 <a class="header-anchor" href="#收益与亮点" aria-label="Permalink to &quot;收益与亮点&quot;">​</a></h3><ul><li><strong>存储空间大幅提升</strong>：从 60TB + TrueNAS 扩展到远超以往的容量，且成本更低</li><li><strong>未来扩容成本效益高</strong>：同事提出需要存储每张 30GB 显微镜晶圆图像时，完全不是问题</li><li><strong>彻底摆脱厂商锁定</strong>：以往 SAN 设备总是由厂商主导 EOL 时间表，Ceph 完全由自己掌控</li><li><strong>知识沉淀价值</strong>：从黑盒 SAN 转变为深度理解存储系统内部机制，知识与技能成为核心资产</li><li><strong>活跃的社区支持</strong>：Slack 频道、Reddit、邮件列表、AMA 活动等，社区响应积极</li></ul><p>NFS 已完成迁移至 CephFS，OpenAFS 的替换工作正在进行中。</p>',60)])])}const S=e(l,[["render",i]]);export{c as __pageData,S as default};
